'''
Example 1:

Input: numbers = [2,7,11,15], target = 9
Output: [1,2]
Explanation: The sum of 2 and 7 is 9. Therefore, index1 = 1, index2 = 2. We return [1, 2].
Example 2:

Input: numbers = [2,3,4], target = 6
Output: [1,3]
Explanation: The sum of 2 and 4 is 6. Therefore index1 = 1, index2 = 3. We return [1, 3].
Example 3:

Input: numbers = [-1,0], target = -1
Output: [1,2]
Explanation: The sum of -1 and 0 is -1. Therefore index1 = 1, index2 = 2. We return [1, 2].
'''

def twoSum(numbers: list[int], target: int) -> list[int]:
    lenNum = len(numbers)
    pointer1 = 0
    pointer2 = lenNum-1
    while pointer1 <= pointer2:
        #print(f"Num1: {numbers[pointer1]} : Num2: {numbers[pointer2]}")
        #print(f"Sum: {numbers[pointer1] + numbers[pointer2]}")
        if numbers[pointer1] + numbers[pointer2] == target:
            return [pointer1+1, pointer2+1]
        if numbers[pointer1] + numbers[pointer2] <= target:
            pointer1 += 1
            continue
        if numbers[pointer1] + numbers[pointer2] >= target:
            pointer2 -= 1
            continue
    return [-1,-1]

def twoSum2(numbers: list[int], target: int) -> list[int]:
    numbersLen = len(numbers)
    leftPointer = 0
    rightPointer = numbersLen-1
    print(f"Left: {leftPointer}/{numbers[leftPointer]} Right: {rightPointer}/{numbers[rightPointer]}")
    while leftPointer < rightPointer:
        currentSum = numbers[leftPointer] + numbers[rightPointer]
        if currentSum == target:
            return [leftPointer+1,rightPointer+1]
        if currentSum < target:
            leftPointer += 1
            continue
        if currentSum > target:
            rightPointer -= 1
            continue
    return [0,0]

print(twoSum([2,7,11,15], 9))   # [1,2]
print(twoSum([2,3,4], 6))       # [1,3]
print(twoSum([-1,0], -1))       # [1,2]
print(twoSum([5,25,75], 100))   # [2,3]
